import{_ as i,l as n,o as t,c as s,v as e,p as l,x as o,d as h,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Bootstrap 在金融","description":"","frontmatter":{"title":"Bootstrap 在金融","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bootstrap-finance.md","filePath":"quant/bootstrap-finance.md","lastUpdated":1789023840000}'),d={name:"quant/bootstrap-finance.md"};function c(A,a,B,u,f,m){const r=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="bootstrap-在金融" tabindex="-1">Bootstrap 在金融 <a class="header-anchor" href="#bootstrap-在金融" aria-label="Permalink to &quot;Bootstrap 在金融&quot;">​</a></h1><div class="epigraph"><p>渐近标准误把「样本量已经够大、分布已经够正态」写进临界值；自助法则用样本自己的经验分布去重算统计量，金融里这两条常常同时不成立。</p><footer>—— Efron, Bootstrap Methods: Another Look at the Jackknife, Annals of Statistics, 1979；相依数据见 Künsch 块自助与 Politis–Romano 平稳自助</footer></div><p><a href="/quant/clustered-se">聚类标准误</a> 仍是一阶渐近：聚类数 \\(G\\to\\infty\\)、\\(G_c\\) 近似正态。金融里 \\(G\\) 经常是 40 个行业、20 年、十几个事件；收益肥尾，一次闪崩主导二次矩。此时三明治的 \\(t\\) 名义水平不可信。自助法用重抽样逼近 \\(\\hat\\beta\\) 或检验统计量的有限样本分布。本课缺口是：<strong>金融不能对行做 i.i.d. 自助</strong>——那会拆掉 Newey–West 与聚类刚刚承认的依赖。后课固定效应、工具变量会把自助用在更脆的估计量上；这里先把合法的重抽样单位钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要对 \\(T(\\hat\\theta-\\theta)\\) 的分布做推断，经典做法用正态极限。Efron 的自助把样本当作总体，从中再抽 \\(B\\) 次，得到 \\(\\{T^*_b\\}\\)，用其分位当临界值。一致性要求自助数据生成过程与真依赖同类：独立则有放回抽观测；时间序列则抽块；面板则抽公司（或抽年）。</p><p>问题是选对<strong>重抽样原子</strong>。对日收益回归做普通对对自助（pairs bootstrap），等于宣布残差无序列相关，会把 HAC 问题再藏起来。对重叠长期收益做残差自助而不切块，会低估重叠造成的方差。对象是检验的水平与区间覆盖，不是「再算一个更大的标准误」。</p><h3 id="哪一种自助对应哪一种依赖" tabindex="-1">哪一种自助对应哪一种依赖 <a class="header-anchor" href="#哪一种自助对应哪一种依赖" aria-label="Permalink to &quot;哪一种自助对应哪一种依赖&quot;">​</a></h3><ul><li><strong>对对 / 残差自助</strong>：截面近似独立、异方差（残差自助要同方差或要按 \\(x\\) 分层）。</li><li><strong>块自助（Künsch）或平稳自助（Politis–Romano）</strong>：时间序列短记忆；块长类似 HAC 带宽。</li><li><strong>聚类自助</strong>：抽公司或抽月，组内整块保留。</li><li><strong>野生自助（wild bootstrap）</strong>：异方差、杠杆点；对残差乘 Rademacher 权重，适合肥尾。</li></ul><p><span class="marginnote">自助不是「让结果变显著」的旋钮。若经济上只有 12 次独立危机，无论 \\(B=10000\\) 都变不出第 13 次危机。\\(B\\) 只降低蒙特卡洛误差，不增加信息。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>回归。</strong> 对对自助：重抽 \\((y_i,x_i)\\)。残差自助：固定 \\(X\\)，重抽 \\(\\hat u\\)（可野生）。金融截面异方差用野生更稳。报告百分位区间与 \\(B\\)；偏差校正（BCa）在强偏斜率（如 \\(R^2\\)、夏普）上值得。</p><p><strong>时间序列。</strong> 块长 \\(L\\) 与 Newey–West 的 \\(L\\) 同阶。平稳自助随机切块，对边缘效应更平滑。单位根、长记忆下普通块自助不一致，应换筛自助或先差分。波动预测的 QLIKE 比较用 Diebold–Mariano 的自助版本，见后课 <a href="/quant/qlike-vol-forecast-eval">QLIKE</a>。</p><p><strong>多重规则。</strong> White 的 Reality Check 与 <a href="/quant/hansen-spa">Hansen SPA</a> 本身就是自助检验：对最大绩效统计量重抽样。这里的教训是：自助的原假设必须对准你要的命题（有没有优于基准的规则），而不是对准单个系数。</p><h3 id="与渐近并列-而不是互相替代" tabindex="-1">与渐近并列，而不是互相替代 <a class="header-anchor" href="#与渐近并列-而不是互相替代" aria-label="Permalink to &quot;与渐近并列，而不是互相替代&quot;">​</a></h3><p>大 \\(T\\)、薄尾、依赖短，HAC/聚类与自助应接近；不接近时，先查重抽样是否拆了依赖，再查渐近是否太乐观。小样本里自助可以仍偏：块太短像 White，块太长像只有几个观测。应报告块长敏感性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自助有效，是因为经验测度在弱定律下靠近真测度，连续泛函（均值、分位、根）的分布被带着走。依赖数据要把经验测度定义在块上，否则经验测度是错误总体（独立乘积）的。肥尾下均值的自助可以不一致（无限方差）；金融收益接近这个边界，应对收益用稳健泛函，或对 \\(t\\) 统计量自助（studentize）而不是对 \\(\\hat\\beta\\) 自己。</p><p>Studentize 的机制：先除以每次自助样本的标准误，临界值针对 \\(t^*\\) 而不是 \\(\\hat\\beta^*\\)。异方差与偏度对 \\(t\\) 的影响部分被吸收，覆盖通常更好。这是 Horowitz 强调的「对枢轴量自助」。</p><p><span class="marginnote">夏普比率、最大回撤、最优权重是高度非线性泛函，自助分布会很偏。先 studentize，并报告中位数与百分位，不要只报自助标准误再当正态用——那把自助退回一阶渐近。</span></p><h3 id="非法自助的典型样子" tabindex="-1">非法自助的典型样子 <a class="header-anchor" href="#非法自助的典型样子" aria-label="Permalink to &quot;非法自助的典型样子&quot;">​</a></h3><p>用全样本估 \\(\\beta\\) 再在样本内自助 \\(t\\)，却把排序、变量选择、winsor 阈值留在自助之外——过拟合被当成总体特征。合法做法：每条自助路径重做全部预处理。事件研究自助应对事件（公司–日）抽样，而不是对日历日打散事件窗。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(T=60\\) 个月的因子回归，块自助块长 6 则大约 10 块，分布很噪。高频 tick 上块自助计算贵，应先聚合。GMM 过度识别时，自助权重矩阵要按 Hall 与 Horowitz 的方式中心化，否则过度拒绝。</p><p>工程：截面用野生或聚类自助；时间序列用平稳块；\\(B\\ge 999\\) 报 p 值网格。不要对已经双向聚类的面板再做拆行自助当「稳健」。不要用自助 p 值替代识别策略。与 <a href="/quant/white-reality-check">White Reality Check</a> 相连时，自助的是最大统计量，不是单个 alpha。</p>',24)),(t(),l(p,null,{default:o(()=>[E(r,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8E%9F%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20A%7B%22%E4%BE%9D%E8%B5%96%E7%BB%93%E6%9E%84%22%7D%0A%20%20A%20--%3E%7C%E6%88%AA%E9%9D%A2%E5%BC%82%E6%96%B9%E5%B7%AE%7C%20W%5B%22%E9%87%8E%E7%94%9F%20%2F%20%E5%AF%B9%E5%AF%B9%E8%87%AA%E5%8A%A9%22%5D%0A%20%20A%20--%3E%7C%E6%97%B6%E9%97%B4%E5%BA%8F%E5%88%97%7C%20B%5B%22%E5%9D%97%20%2F%20%E5%B9%B3%E7%A8%B3%E8%87%AA%E5%8A%A9%22%5D%0A%20%20A%20--%3E%7C%E9%9D%A2%E6%9D%BF%7C%20C%5B%22%E6%8C%89%E5%85%AC%E5%8F%B8%E6%88%96%E6%8C%89%E6%9C%88%E6%95%B4%E7%B0%87%E6%8A%BD%22%5D%0A%20%20W%20--%3E%20T%5B%22%E7%BB%9F%E8%AE%A1%E9%87%8F%20T*%20%E7%9A%84%E7%BB%8F%E9%AA%8C%E5%88%86%E5%B8%83%22%5D%0A%20%20B%20--%3E%20T%0A%20%20C%20--%3E%20T%0A%20%20T%20--%3E%20CI%5B%22%E5%88%86%E4%BD%8D%E5%8C%BA%E9%97%B4%20%2F%20%E5%AD%A6%E7%94%9F%E5%8C%96%20p%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>金融样本短、尾厚、依赖强时，一阶三明治的名义水平不可靠，应对枢轴量做自助。</li><li>重抽样原子必须匹配依赖：块对应 HAC，簇对应聚类，禁止拆行 i.i.d. 自助。</li><li>\\(B\\) 只减模拟误差；独立危机次数才是信息量。</li><li>预处理、选择、重叠必须在每条路径内重做。</li><li>出处：Efron, <em>Annals of Statistics</em>, 1979；块自助见 Künsch, <em>Annals of Statistics</em>, 1989；平稳自助见 Politis and Romano, <em>Journal of the American Statistical Association</em>, 1994。</li></ul>',2))])}const C=i(d,[["render",c]]);export{b as __pageData,C as default};
